fn convert(input:&str,bracketed:bool,_pool:&Arc<Budget>)->String{let text=input.replace("\r\n","\r").replace('\n',"\r");if bracketed{let text=text.replace("\x1b[201~","");format!("\x1b[200~{text}\x1b[201~")}else{text}}
fn bytes(text:&String)->&[u8]{text.as_bytes()}
fn decode_utf8(input:&[u8],_pool:&Arc<Budget>)->String{ClipboardRead::default().utf8(input).unwrap()}
fn decoded(text:&String)->&str{text}

